pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(value) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(value.into()));
    }
    if let Some(value) = bytes.strip_prefix("v:2|heartbeat:") {
        if let Ok(sequence) = value.parse() {
            return Ok(Msg::Heartbeat(sequence));
        }
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("v:2|hello:{value}"),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat:{sequence}"),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn roundtrips_v2_hello() {
        let msg = Msg::Hello("world".into());
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Hello(value)) if value == "world"));
    }

    #[test]
    fn roundtrips_heartbeat() {
        let msg = Msg::Heartbeat(42);
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }
}
